import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Sidebar from './Sidebar';
import StudentProfileSettings from './StudentProfileSettings';

export default function StudentDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [timetable, setTimetable] = useState([]);
  const [materials, setMaterials] = useState([]);
  const [activities, setActivities] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [myFeedbacks, setMyFeedbacks] = useState([]);

  // Student Info
  const studentName = user?.name || "Student";
  const studentGrade = user?.grade || "Grade 8";
  const studentSubjects = user?.subjects 
    ? (Array.isArray(user.subjects) ? user.subjects : String(user.subjects).split(',').map(s => s.trim()).filter(Boolean)) 
    : ["Mathematics", "Science", "English"];

  // Filters & States
  const [selectedSubject, setSelectedSubject] = useState(studentSubjects[0] || 'Mathematics');
  const [materialLessonFilter, setMaterialLessonFilter] = useState('All');
  const [activityLessonFilter, setActivityLessonFilter] = useState('All');
  const [activityTypeFilter, setActivityTypeFilter] = useState('All');

  const [activityAnswers, setActivityAnswers] = useState({});
  const [activeVideo, setActiveVideo] = useState(null); 
  const [activeQuiz, setActiveQuiz] = useState(null);
  const [quizQuestions, setQuizQuestions] = useState([]);
  const [userAnswers, setUserAnswers] = useState({});
  const [quizResult, setQuizResult] = useState(null);

  const [feedback, setFeedback] = useState({ subject: '', message: '' });

  useEffect(() => {
    const targetGradeNum = studentGrade.replace(/\D/g, '');

    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        const data = res.data || [];
        const filtered = data.filter(t => (t.grade || '').replace(/\D/g, '') === targetGradeNum);
        setTimetable(filtered.length > 0 ? filtered : data);
      }).catch(() => setTimetable([]));

    axios.get('http://localhost:8082/api/learning-materials').then(res => setMaterials(res.data || [])).catch(() => setMaterials([]));
    axios.get('http://localhost:8082/api/lesson-activities-list').then(res => setActivities(res.data || [])).catch(() => setActivities([]));
    axios.get('http://localhost:8082/api/quizzes').then(res => setQuizzes(res.data || [])).catch(() => setQuizzes([]));
    axios.get('http://localhost:8082/api/feedbacks').then(res => setMyFeedbacks(res.data || [])).catch(() => setMyFeedbacks([]));
  }, [studentGrade]);

  const cleanTxt = (str) => (str || '').replace(/\$|\{|\}/g, '');
  const parseNum = (str) => parseInt((str || '').replace(/\D/g, '')) || 0;

  const getEmbedUrl = (url) => {
    if (!url) return null;
    let u = url.trim();
    if (u.includes('watch?v=')) return u.replace('watch?v=', 'embed/').split('&')[0];
    if (u.includes('youtu.be/')) return u.replace('youtu.be/', 'youtube.com/embed/').split('?')[0];
    return u;
  };

  const getLessonFolder = (title) => {
    const match = (title || '').match(/lesson\s*\d+/i);
    return match ? match[0].toUpperCase().replace('LESSON', 'Lesson ') : 'General Lessons';
  };

  const getCleanTitle = (title, isVideo) => {
    let clean = (title || '').replace(/lesson\s*\d+/gi, '').replace(/video/gi, '').replace(/[-_]/g, '').trim();
    return clean || (isVideo ? 'Video Tutorial & Explanation' : 'Theory Note & Exercises (PDF)');
  };

  const getActivityType = (act) => {
    const type = (act.question_type || '').toLowerCase();
    if (type.includes('true') || type.includes('tf')) return 'True/False';
    if (type.includes('mcq')) return 'MCQ';
    if (type.includes('short')) return 'Short Answer';

    const optA = (act.option_a || '').toUpperCase().trim();
    if (optA === 'TRUE' || !act.option_c) return 'True/False';
    if (act.option_c || act.option_d) return 'MCQ';
    return 'Short Answer';
  };

  const subjectMaterials = materials.filter(m => (m.subject || m.subject_name || '').toLowerCase().includes(selectedSubject.toLowerCase()));
  const materialLessons = Array.from(new Set(subjectMaterials.map(m => getLessonFolder(m.title)))).sort((a, b) => parseNum(b) - parseNum(a));

  const groupedMaterials = subjectMaterials
    .filter(m => materialLessonFilter === 'All' || getLessonFolder(m.title) === materialLessonFilter)
    .reduce((acc, item) => {
      const les = getLessonFolder(item.title);
      if (!acc[les]) acc[les] = [];
      acc[les].push(item);
      return acc;
    }, {});

  const sortedMaterialFolderKeys = Object.keys(groupedMaterials).sort((a, b) => parseNum(b) - parseNum(a));

  const subjectActivities = activities.filter(a => (a.subject || a.subject_name || '').toLowerCase().includes(selectedSubject.toLowerCase()));
  const activityLessons = Array.from(new Set(subjectActivities.map(a => a.lesson_name?.trim()).filter(Boolean))).sort((a, b) => parseNum(b) - parseNum(a));

  const filteredActivities = subjectActivities.filter(a => {
    if (activityLessonFilter !== 'All' && (a.lesson_name || '').toLowerCase() !== activityLessonFilter.toLowerCase()) return false;
    if (activityTypeFilter !== 'All' && getActivityType(a) !== activityTypeFilter) return false;
    return true;
  });

  const handleStartQuiz = (quiz) => {
    setActiveQuiz(quiz);
    setUserAnswers({});
    setQuizResult(null);
    axios.get('http://localhost:8082/api/question-bank')
      .then(res => setQuizQuestions((res.data || []).filter(q => q.quiz_id === quiz.id || q.grade === studentGrade)))
      .catch(() => setQuizQuestions([]));
  };

  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const timeSlots = ['08:00 AM', '10:30 AM', '01:00 PM', '03:30 PM'];

  return (
    <div style={styles.container}>
      {/* Shared Reusable Sidebar Component */}
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        title="STUDENT PORTAL" 
      />

      <div style={styles.mainContent}>
        
        {/* 1️⃣ DASHBOARD OVERVIEW TAB */}
        {activeTab === 'dashboard' && (
          <div>
            <div style={styles.banner}>
              <h1 style={{ margin: 0, fontSize: '24px', fontWeight: 'bold' }}>Welcome back, {studentName}! 🎓</h1>
              <p style={{ margin: '6px 0 0 0', fontSize: '14px', color: '#e2e8f0', opacity: 0.9 }}>Access your personalized classroom workflows, live timetables, and learning modules.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '18px', marginBottom: '24px' }}>
              {[
                { label: 'Assigned Grade', val: studentGrade, color: '#8b5cf6', textCol: '#6d28d9' },
                { label: 'Enrolled Courses', val: `${studentSubjects.length} Subjects`, color: '#f59e0b', textCol: '#d97706' },
                { label: 'Study Materials', val: `${materials.length} Items`, color: '#145c2e', textCol: '#145c2e' },
                { label: 'Available Exams', val: `${quizzes.length} Quizzes`, color: '#3b82f6', textCol: '#1d4ed8' }
              ].map((card, i) => (
                <div key={i} style={{ ...styles.statCard, borderLeft: `5px solid ${card.color}` }}>
                  <p style={styles.statLabel}>{card.label}</p>
                  <h3 style={{ margin: '4px 0 0 0', fontSize: '20px', fontWeight: 'bold', color: card.textCol }}>{card.val}</h3>
                </div>
              ))}
            </div>

            <div style={styles.whiteBox}>
              <p style={{ margin: '0 0 12px 0', fontSize: '14px', fontWeight: 'bold', color: '#145c2e' }}>
                📌 Select Course Subject to View Specific Materials & Activities:
              </p>
              <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
                {studentSubjects.map((sub, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => { setSelectedSubject(sub); setMaterialLessonFilter('All'); setActivityLessonFilter('All'); setActiveTab('materials'); }}
                    style={{ ...styles.pillBtn, backgroundColor: selectedSubject === sub ? '#145c2e' : '#f0fdf4', color: selectedSubject === sub ? '#fff' : '#145c2e' }}
                  >
                    📖 {sub} (Go to Subject)
                  </button>
                ))}
              </div>
            </div>

            <div style={{ ...styles.whiteBox, marginTop: '24px' }}>
              <h3 style={{ margin: '0 0 18px 0', fontSize: '16px', color: '#1e293b', fontWeight: 'bold' }}>🗓️ Live Weekly Class Timetable ({studentGrade})</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '13.5px' }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                    <th style={{ padding: '12px', textAlign: 'left', color: '#64748b' }}>Time Slot</th>
                    {daysOfWeek.map(day => <th key={day} style={{ padding: '12px', color: '#64748b' }}>{day}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {timeSlots.map(slot => (
                    <tr key={slot} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '14px 10px', fontWeight: 'bold', textAlign: 'left', color: '#334155' }}>{slot}</td>
                      {daysOfWeek.map(day => {
                        const match = timetable.find(t => (t.day || '').toLowerCase().startsWith(day.toLowerCase()) && (t.time_slot || '').replace(/\s/g, '').toLowerCase() === slot.replace(/\s/g, '').toLowerCase());
                        return (
                          <td key={day} style={{ padding: '6px' }}>
                            {match ? (
                              <div style={styles.classBadge}>
                                <div style={{ fontWeight: 'bold' }}>{match.subject}</div>
                                <div style={{ fontSize: '11px', color: '#15803d' }}>👨‍🏫 {match.teacher}</div>
                              </div>
                            ) : <span style={{ color: '#cbd5e1' }}>-</span>}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* 2️⃣ LEARNING MATERIALS TAB */}
        {activeTab === 'materials' && (
          <div style={styles.whiteBox}>
            <div style={styles.tabHeader}>
              <div>
                <h2 style={{ margin: 0, fontSize: '20px', color: '#145c2e', fontWeight: 'bold' }}>
                  📚 Course Learning Materials - <span style={{ color: '#16a34a' }}>{selectedSubject}</span> ({studentGrade})
                </h2>
                <p style={{ margin: '4px 0 0 0', fontSize: '13px', color: '#64748b' }}>Organized lesson-by-lesson (Newest lesson appears on top)</p>
              </div>

              <div style={{ display: 'flex', gap: '8px' }}>
                {studentSubjects.map(sub => (
                  <button key={sub} onClick={() => { setSelectedSubject(sub); setMaterialLessonFilter('All'); }} style={{ ...styles.filterTab, backgroundColor: selectedSubject === sub ? '#145c2e' : '#f1f5f9', color: selectedSubject === sub ? '#fff' : '#475569' }}>
                    {sub}
                  </button>
                ))}
              </div>
            </div>

            <div style={styles.filterBar}>
              <span style={{ fontSize: '13.5px', fontWeight: 'bold', color: '#145c2e' }}>📘 Filter Lesson Folder:</span>
              <select value={materialLessonFilter} onChange={(e) => setMaterialLessonFilter(e.target.value)} style={styles.selectInput}>
                <option value="All">All Lessons Folder</option>
                {materialLessons.map(les => <option key={les} value={les}>{les}</option>)}
              </select>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              {sortedMaterialFolderKeys.map((lessonTitle) => (
                <div key={lessonTitle} style={styles.folderBox}>
                  <div style={styles.folderHeader}>
                    <h3 style={{ margin: 0, fontSize: '15px', color: '#145c2e', fontWeight: 'bold' }}>📁 {lessonTitle}</h3>
                    <span style={styles.countBadge}>{groupedMaterials[lessonTitle].length} Item(s)</span>
                  </div>

                  <div style={{ padding: '14px', display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '12px' }}>
                    {groupedMaterials[lessonTitle].map(m => {
                      const isVideo = (m.material_type || '').toLowerCase().includes('video') || (m.file_path || '').includes('youtube') || (m.file_path || '').includes('youtu.be');
                      const embedUrl = getEmbedUrl(m.file_path);
                      const displayTitle = getCleanTitle(m.title, isVideo);

                      return (
                        <div key={m.id} style={styles.compactMaterialCard}>
                          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                            <span style={{ fontSize: '11px', color: isVideo ? '#dc2626' : '#2563eb', backgroundColor: isVideo ? '#fef2f2' : '#eff6ff', padding: '3px 8px', borderRadius: '6px', fontWeight: 'bold' }}>
                              {isVideo ? '🎥 Video Lesson' : '📄 PDF Document'}
                            </span>
                          </div>
                          
                          <h4 style={{ margin: '0 0 12px 0', fontSize: '13.5px', color: '#1e293b', fontWeight: '600', lineHeight: '1.3' }}>
                            {displayTitle}
                          </h4>

                          <div>
                            {isVideo ? (
                              <button onClick={() => setActiveVideo({ url: embedUrl, title: `${lessonTitle} - Video` })} style={{ ...styles.actionBtnCompact, backgroundColor: '#dc2626' }}>
                                ▶️ Watch Video
                              </button>
                            ) : (
                              <a href={`http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={{ ...styles.actionBtnCompact, backgroundColor: '#145c2e' }}>
                                👁️ View / Download PDF
                              </a>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}

              {sortedMaterialFolderKeys.length === 0 && (
                <div style={{ textAlign: 'center', padding: '50px', color: '#94a3b8', fontStyle: 'italic', fontSize: '15px' }}>
                  No study materials uploaded for <b>{selectedSubject}</b> yet.
                </div>
              )}
            </div>
          </div>
        )}

        {/* Video Player Modal */}
        {activeVideo && (
          <div style={styles.modalOverlay}>
            <div style={styles.videoModal}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px', borderBottom: '1px solid #e2e8f0', paddingBottom: '10px' }}>
                <h3 style={{ margin: 0, fontSize: '16px', color: '#1e293b', fontWeight: 'bold' }}>🎥 {activeVideo.title}</h3>
                <button onClick={() => setActiveVideo(null)} style={styles.closeBtn}>✖ Close Player</button>
              </div>
              <div style={{ width: '100%', height: '400px', borderRadius: '10px', overflow: 'hidden', backgroundColor: '#000' }}>
                <iframe src={activeVideo.url} title={activeVideo.title} style={{ width: '100%', height: '100%', border: 'none' }} allowFullScreen></iframe>
              </div>
            </div>
          </div>
        )}

        {/* 3️⃣ LESSON ACTIVITIES TAB */}
        {activeTab === 'activities' && (
          <div style={styles.whiteBox}>
            <div style={styles.tabHeader}>
              <div>
                <h2 style={{ margin: 0, fontSize: '20px', color: '#145c2e', fontWeight: 'bold' }}>
                  🧩 Lesson Activities - <span style={{ color: '#16a34a' }}>{selectedSubject}</span>
                </h2>
                <p style={{ margin: '4px 0 0 0', fontSize: '13px', color: '#64748b' }}>Interactive practice tasks curated for {selectedSubject}</p>
              </div>
              
              <div style={{ display: 'flex', gap: '8px' }}>
                {studentSubjects.map(sub => (
                  <button key={sub} onClick={() => { setSelectedSubject(sub); setActivityLessonFilter('All'); }} style={{ ...styles.filterTab, backgroundColor: selectedSubject === sub ? '#145c2e' : '#f1f5f9', color: selectedSubject === sub ? '#fff' : '#475569' }}>
                    {sub}
                  </button>
                ))}
              </div>
            </div>

            <div style={{ ...styles.filterBar, justifyContent: 'space-between' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#145c2e' }}>📘 Select Lesson:</span>
                <select value={activityLessonFilter} onChange={(e) => setActivityLessonFilter(e.target.value)} style={styles.selectInput}>
                  <option value="All">All Lessons</option>
                  {activityLessons.map(les => <option key={les} value={les}>{les}</option>)}
                </select>
              </div>

              <div style={{ display: 'flex', gap: '8px' }}>
                {['All', 'True/False', 'MCQ', 'Short Answer'].map(t => (
                  <button 
                    key={t} 
                    onClick={() => setActivityTypeFilter(t)}
                    style={{ ...styles.pillBtn, backgroundColor: activityTypeFilter === t ? '#145c2e' : '#fff', color: activityTypeFilter === t ? '#fff' : '#475569', border: '1px solid #cbd5e1' }}
                  >
                    {t === 'All' ? '📋 All Types' : t}
                  </button>
                ))}
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '18px' }}>
              {filteredActivities.map((act, index) => {
                const type = getActivityType(act);

                return (
                  <div key={act.id} style={styles.activityCard}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                      <span style={{ fontSize: '14.5px', fontWeight: 'bold', color: '#145c2e' }}>
                        Question {String(index + 1).padStart(2, '0')}
                      </span>
                      <span style={{ fontSize: '11.5px', backgroundColor: '#ecfdf5', color: '#15803d', border: '1px solid #bbf7d0', padding: '3px 10px', borderRadius: '12px', fontWeight: 'bold' }}>
                        {type}
                      </span>
                    </div>

                    <p style={{ fontSize: '15px', margin: '0 0 18px 0', color: '#1e293b', fontWeight: '500', lineHeight: '1.6' }}>
                      {cleanTxt(act.question_text)}
                    </p>

                    {type === 'True/False' && (
                      <div style={{ display: 'flex', gap: '14px', maxWidth: '420px' }}>
                        {['TRUE', 'FALSE'].map(opt => (
                          <button
                            key={opt}
                            onClick={() => setActivityAnswers({ ...activityAnswers, [act.id]: opt })}
                            style={{
                              flex: 1, padding: '12px', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13.5px',
                              border: activityAnswers[act.id] === opt ? '2px solid #145c2e' : '1px solid #cbd5e1',
                              backgroundColor: activityAnswers[act.id] === opt ? '#d1fae5' : '#ffffff',
                              color: activityAnswers[act.id] === opt ? '#145c2e' : '#475569'
                            }}
                          >
                            {opt === 'TRUE' ? '✅ TRUE' : '❌ FALSE'}
                          </button>
                        ))}
                      </div>
                    )}

                    {type === 'MCQ' && (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', maxWidth: '750px' }}>
                        {[
                          { k: 'A', txt: act.option_a }, { k: 'B', txt: act.option_b },
                          { k: 'C', txt: act.option_c }, { k: 'D', txt: act.option_d }
                        ].filter(o => Boolean(o.txt)).map(o => (
                          <div 
                            key={o.k}
                            onClick={() => setActivityAnswers({ ...activityAnswers, [act.id]: o.k })}
                            style={{
                              padding: '12px 16px', borderRadius: '10px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '10px', fontSize: '14px',
                              border: activityAnswers[act.id] === o.k ? '2px solid #145c2e' : '1px solid #e2e8f0',
                              backgroundColor: activityAnswers[act.id] === o.k ? '#f0fdf4' : '#ffffff',
                              color: activityAnswers[act.id] === o.k ? '#145c2e' : '#334155',
                              fontWeight: activityAnswers[act.id] === o.k ? 'bold' : 'normal'
                            }}
                          >
                            <span style={{ backgroundColor: activityAnswers[act.id] === o.k ? '#145c2e' : '#f1f5f9', color: activityAnswers[act.id] === o.k ? '#fff' : '#64748b', borderRadius: '50%', width: '26px', height: '26px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 'bold' }}>
                              {o.k}
                            </span>
                            {cleanTxt(o.txt)}
                          </div>
                        ))}
                      </div>
                    )}

                    {type === 'Short Answer' && (
                      <input 
                        type="text" 
                        placeholder="Type your final answer here..."
                        value={activityAnswers[act.id] || ''}
                        onChange={(e) => setActivityAnswers({ ...activityAnswers, [act.id]: e.target.value })}
                        style={{ ...styles.inputLarge, maxWidth: '600px' }}
                      />
                    )}
                  </div>
                );
              })}

              {filteredActivities.length === 0 && (
                <p style={{ color: '#94a3b8', fontStyle: 'italic', padding: '30px', textAlign: 'center', fontSize: '14px' }}>
                  No activities published for <b>{activityLessonFilter !== 'All' ? activityLessonFilter : selectedSubject}</b> yet.
                </p>
              )}
            </div>
          </div>
        )}

        {/* 4️⃣ ONLINE EXAMS TAB */}
        {activeTab === 'exams' && (
          <div style={styles.whiteBox}>
            <h2 style={{ marginTop: 0, fontSize: '20px', color: '#145c2e', fontWeight: 'bold' }}>📝 Online Formal Exams & Evaluations</h2>

            {!activeQuiz ? (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '18px', marginTop: '20px' }}>
                {quizzes.map(q => (
                  <div key={q.id} style={{ border: '1px solid #bbf7d0', padding: '22px', borderRadius: '14px', backgroundColor: '#f0fdf4' }}>
                    <h3 style={{ margin: '0 0 6px 0', color: '#145c2e', fontSize: '17px' }}>{q.title}</h3>
                    <p style={{ margin: '0 0 16px 0', fontSize: '13px', color: '#15803d' }}>Grade: {q.grade} | Duration: {q.duration_minutes || 30} Mins</p>
                    <button onClick={() => handleStartQuiz(q)} style={styles.primaryBtn}>🚀 Start Exam Now</button>
                  </div>
                ))}
              </div>
            ) : (
              <div style={{ marginTop: '20px', padding: '22px', border: '2px solid #145c2e', borderRadius: '14px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #cbd5e1', paddingBottom: '12px' }}>
                  <h3 style={{ margin: 0, fontSize: '17px' }}>Exam: {activeQuiz.title}</h3>
                  <button onClick={() => setActiveQuiz(null)} style={{ background: '#dc2626', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>Exit Exam</button>
                </div>

                {quizResult ? (
                  <div style={{ textAlign: 'center', padding: '35px 0' }}>
                    <h2 style={{ color: '#145c2e', margin: 0 }}>🎉 Exam Submitted!</h2>
                    <h1 style={{ fontSize: '54px', margin: '10px 0', color: '#145c2e' }}>{quizResult.score}%</h1>
                    <button onClick={() => setActiveQuiz(null)} style={{ ...styles.primaryBtn, marginTop: '18px' }}>Back to Exams List</button>
                  </div>
                ) : (
                  <div style={{ marginTop: '20px' }}>
                    {quizQuestions.map((q, idx) => (
                      <div key={q.id} style={{ marginBottom: '18px', padding: '16px', backgroundColor: '#f8fafc', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                        <p style={{ fontWeight: 'bold', margin: '0 0 12px 0', fontSize: '14.5px' }}>Q{idx + 1}. {cleanTxt(q.question_text)}</p>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                          {['A', 'B', 'C', 'D'].map(opt => (
                            <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', fontSize: '13.5px' }}>
                              <input type="radio" name={`q_${q.id}`} value={opt} checked={userAnswers[q.id] === opt} onChange={() => setUserAnswers({ ...userAnswers, [q.id]: opt })} style={{ accentColor: '#145c2e' }} />
                              <b>{opt})</b> {cleanTxt(q[`option_${opt.toLowerCase()}`])}
                            </label>
                          ))}
                        </div>
                      </div>
                    ))}
                    <button onClick={() => setQuizResult({ score: 85 })} style={{ ...styles.primaryBtn, width: '100%', padding: '14px', fontSize: '15px' }}>Submit Exam Answers 📤</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* 5️⃣ TEACHER FEEDBACK TAB */}
        {activeTab === 'feedback' && (
          <div style={styles.whiteBox}>
            <h2 style={{ marginTop: 0, fontSize: '20px', color: '#145c2e', fontWeight: 'bold' }}>💬 Teacher Feedback & Support Forum</h2>
            <form onSubmit={(e) => { e.preventDefault(); alert("Feedback sent!"); setMyFeedbacks([...myFeedbacks, { id: Date.now(), subject: feedback.subject, message: feedback.message, status: 'Pending' }]); setFeedback({ subject: '', message: '' }); }} style={{ display: 'flex', flexDirection: 'column', gap: '14px', backgroundColor: '#f8fafc', padding: '22px', borderRadius: '14px', border: '1px solid #e2e8f0', marginTop: '16px' }}>
              <input type="text" placeholder="Subject / Query Title" value={feedback.subject} onChange={e => setFeedback({ ...feedback, subject: e.target.value })} style={styles.inputLarge} />
              <textarea rows="4" placeholder="Type your message for teachers..." value={feedback.message} onChange={e => setFeedback({ ...feedback, message: e.target.value })} style={{ ...styles.inputLarge, resize: 'none' }}></textarea>
              <button type="submit" style={styles.primaryBtn}>📩 Send Message to Teacher</button>
            </form>
          </div>
        )}

        {/* 6️⃣ PROFILE SETTINGS TAB (Imported Component) */}
        {activeTab === 'settings' && (
          <StudentProfileSettings user={user} />
        )}

      </div>
    </div>
  );
}

const styles = {
  container: { display: 'flex', height: '100vh', width: '100vw', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' },
  mainContent: { flex: 1, padding: '28px', overflowY: 'auto', height: '100vh', boxSizing: 'border-box' },
  banner: { backgroundColor: '#145c2e', borderRadius: '16px', padding: '24px 30px', color: 'white', marginBottom: '24px', boxShadow: '0 10px 20px -5px rgba(20, 92, 46, 0.25)' },
  whiteBox: { backgroundColor: '#fff', padding: '24px', borderRadius: '18px', border: '1px solid #e2e8f0', boxShadow: '0 4px 14px rgba(0,0,0,0.03)' },
  statCard: { backgroundColor: '#fff', padding: '18px', borderRadius: '14px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' },
  statLabel: { margin: 0, fontSize: '12px', color: '#64748b', fontWeight: 'bold' },
  tabHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #f1f5f9', paddingBottom: '16px', marginBottom: '20px' },
  filterBar: { display: 'flex', alignItems: 'center', gap: '12px', backgroundColor: '#f8fafc', padding: '10px 16px', borderRadius: '12px', border: '1px solid #e2e8f0', marginBottom: '22px' },
  folderBox: { border: '1px solid #e2e8f0', borderRadius: '12px', overflow: 'hidden', backgroundColor: '#ffffff', boxShadow: '0 2px 6px rgba(0,0,0,0.02)' },
  folderHeader: { backgroundColor: '#f0fdf4', padding: '10px 16px', borderBottom: '1px solid #bbf7d0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  countBadge: { fontSize: '11px', color: '#16a34a', backgroundColor: '#ffffff', padding: '2px 8px', borderRadius: '8px', fontWeight: 'bold', border: '1px solid #bbf7d0' },
  compactMaterialCard: { backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '10px', padding: '12px 14px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', transition: 'all 0.2s', boxShadow: '0 1px 4px rgba(0,0,0,0.02)' },
  actionBtnCompact: { width: '100%', padding: '7px 10px', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px', textDecoration: 'none', display: 'block', textAlign: 'center', color: '#fff' },
  activityCard: { backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderLeft: '5px solid #145c2e', borderRadius: '12px', padding: '20px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' },
  pillBtn: { padding: '8px 18px', borderRadius: '20px', fontSize: '13px', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.2s' },
  primaryBtn: { backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', textDecoration: 'none', display: 'inline-block', textAlign: 'center', fontSize: '13.5px' },
  filterTab: { border: 'none', padding: '7px 16px', borderRadius: '20px', fontSize: '12.5px', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.2s' },
  selectInput: { padding: '7px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '12.5px', fontWeight: 'bold', backgroundColor: '#fff', color: '#1e293b', cursor: 'pointer' },
  inputLarge: { padding: '11px 15px', borderRadius: '10px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13.5px', backgroundColor: '#fff', width: '100%', boxSizing: 'border-box' },
  classBadge: { backgroundColor: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '8px', padding: '6px', fontSize: '11.5px', color: '#145c2e' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  videoModal: { backgroundColor: 'white', padding: '20px', borderRadius: '16px', width: '720px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' },
  closeBtn: { background: '#dc2626', color: 'white', border: 'none', padding: '6px 14px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' }
};
